import{_ as e,o as a,c as d,a3 as r}from"./chunks/framework.Ba39LDvt.js";const g=JSON.parse('{"title":"自学资源","description":"把上科大课程、公开课和可验证的小项目接起来，按目标而不是收藏数量选择资源。","frontmatter":{"title":"自学资源","description":"把上科大课程、公开课和可验证的小项目接起来，按目标而不是收藏数量选择资源。"},"headers":[],"relativePath":"self-learning/index.md","filePath":"self-learning/index.md","lastUpdated":1795513256000}'),i={name:"self-learning/index.md"};function h(n,t,o,s,l,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="自学资源" tabindex="-1">自学资源 <a class="header-anchor" href="#自学资源" aria-label="Permalink to &quot;自学资源&quot;">​</a></h1><p>资源很多，最难的是决定<strong>现在学什么、做到什么程度就进入下一步</strong>。先在 <a href="/shanghaitech-ic-wiki-dev.github.io/map/">学习地图</a> 确认方向，再从这里选择一门主课、一本参考书和一个练习。公开课用于补概念、换一种解释或扩展项目，不替代本校课程的作业要求与实验规范。</p><h2 id="入门-先确定目标" tabindex="-1">入门：先确定目标 <a class="header-anchor" href="#入门-先确定目标" aria-label="Permalink to &quot;入门：先确定目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/foundations">基础与工具</a></td><td>数学、编程、命令行</td><td>入门</td><td>看不懂公式、不会编译或无法操作服务器时，从这里补短板</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/digital">数字电路</a></td><td>公开课、HDL、仿真</td><td>入门—进阶</td><td>目标是把组合逻辑、时序逻辑写成能验证的硬件</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/analog">模拟电路</a></td><td>教材、公开课、SPICE</td><td>入门—进阶</td><td>从工作点、小信号模型走向放大器、反馈与混合信号模块</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/device">半导体器件</a></td><td>教材、器件仿真</td><td>入门—进阶</td><td>补齐能带、结、MOS 与工艺之间的联系</td></tr></tbody></table><p>不要为了做一个计数器先学完全部数学，也不要为看一篇论文同时开三门公开课。缺哪一项，就补到能解释当前问题；主线仍由自己的课程或项目决定。</p><h2 id="进阶-上科大课程-↔-公开资源" tabindex="-1">进阶：上科大课程 ↔ 公开资源 <a class="header-anchor" href="#进阶-上科大课程-↔-公开资源" aria-label="Permalink to &quot;进阶：上科大课程 ↔ 公开资源&quot;">​</a></h2><p>下表是<strong>主题对照与自学建议，不是学分互认，也不表示教学内容、难度和实验完全相同</strong>。上科大课程名称依据 2026–2027 学年开课计划；开课及要求以教务系统、当学期大纲为准。详细课程信息见 <a href="/shanghaitech-ic-wiki-dev.github.io/courses/">课程导航</a>。</p><table tabindex="0"><thead><tr><th>上科大课程</th><th>可配合的公开课 / 教材</th><th>对照重点</th><th>使用方法</th></tr></thead><tbody><tr><td>CS110 计算机体系结构 I</td><td><a href="https://cs61c.org/" target="_blank" rel="noreferrer">UCB CS61C</a></td><td>C、指令集、流水线与存储层次</td><td>遇到抽象硬件概念时，结合软件执行过程理解</td></tr><tr><td>EE115B 数字电路</td><td><a href="https://6191.mit.edu/" target="_blank" rel="noreferrer">MIT 6.191（原 6.004）</a>、<a href="https://www2.eecs.berkeley.edu/Courses/EECS151/" target="_blank" rel="noreferrer">UCB EECS151</a></td><td>组合逻辑、时序逻辑、有限状态机</td><td>先掌握数电，再选公开练习做独立验证</td></tr><tr><td>EE113 数字集成电路 I</td><td>UCB EECS151、MIT 6.191</td><td>CMOS 到数字系统的层次化设计</td><td>配合本校晶体管级与设计约束内容，注意课程侧重点不同</td></tr><tr><td>EE115A 模拟电路</td><td>Razavi《Fundamentals of Microelectronics》及公开讲授</td><td>器件模型、基本放大器</td><td>先手算，再用仿真核对假设</td></tr><tr><td>EE112 模拟集成电路 I</td><td>Razavi《Design of Analog CMOS Integrated Circuits》</td><td>CMOS 放大器、反馈、稳定性、噪声</td><td>不跳过工作点和小信号分析</td></tr><tr><td>EE150 信号与系统</td><td><a href="https://ocw.mit.edu/" target="_blank" rel="noreferrer">MIT OpenCourseWare</a> 的 Signals and Systems</td><td>线性时不变系统、卷积、变换</td><td>用 Python 画出时域与频域对应关系</td></tr><tr><td>EE219 智能计算系统</td><td><a href="https://efficientml.ai/" target="_blank" rel="noreferrer">MIT 6.5940 / EfficientML</a>、<a href="https://cs217.stanford.edu/" target="_blank" rel="noreferrer">Stanford CS217</a></td><td>数据复用、量化、加速器与系统权衡</td><td>同时记录算法精度、访存量与实测性能</td></tr><tr><td>EE215A 集成电路设计自动化</td><td>EDA 算法教材与 <a href="https://theopenroadproject.org/" target="_blank" rel="noreferrer">OpenROAD</a></td><td>图算法、优化与物理设计</td><td>从小规模算法和合法性检查开始</td></tr></tbody></table><p>更多扩展见 <a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/architecture">体系结构</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/eda-algo">EDA 算法</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/ai-hardware">AI 硬件</a>。教材尽量通过图书馆、作者或出版社的合法渠道获取；公开课某些学期的作业、视频可能不开放。</p><h2 id="实践-把资源变成作品" tabindex="-1">实践：把资源变成作品 <a class="header-anchor" href="#实践-把资源变成作品" aria-label="Permalink to &quot;实践：把资源变成作品&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/eda/open-source">开源 EDA 工具链</a></td><td>本地实验</td><td>入门</td><td>不依赖商用许可证，先完成 HDL 仿真与波形观察</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/eda/environment">EDA 环境与 Linux</a></td><td>环境与工程方法</td><td>入门—进阶</td><td>使用课程环境前，先掌握调度、日志和版本管理</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/competitions/ysyx">一生一芯</a></td><td>系统性项目</td><td>进阶</td><td>适合已有 C、体系结构和 HDL 基础后长期投入</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/research-guide/">科研入门</a></td><td>阅读与研究方法</td><td>进阶</td><td>把“读懂一个资源”转化为可复现的问题与证据</td></tr></tbody></table><p>建议采用“读一节 → 独立做一个小实验 → 检查结果 → 写一段解释”的循环。数字方向可交付带测试平台的 FIFO；模拟方向可交付含工作点、交流和瞬态分析的放大器报告；体系结构方向可交付固定工作负载下的 Cache 参数比较。<strong>截图不是全部证据</strong>，至少保留源码、输入、版本、运行命令、日志和结论适用范围。</p><p>课程作业应遵守学术诚信要求。网上答案、自动生成代码可以帮助定位知识点，但不能替代自己的设计、推导与允许范围内的独立提交。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">上科大信息学院 2026–2027 学年开课计划</a>：课程名称与开课背景。</li><li>公开课及工具的官方主页见上表；对照关系为本站学习建议，而非学校发布的课程等价表。</li></ul>',15)])])}const u=e(i,[["render",h]]);export{g as __pageData,u as default};
